const e=[{Claim:"One competition: a solo singing contest for bonafide school students in two categories, Junior (7th to 9th class) and Senior (10th to 12th class). It is strictly solo: no duets or group performances.",SourceType:"Primary - the event's own rules document",Source:"Acoustica 2026 - Rules & Regulations: Inter-School Solo Singing Competition (Shree JK Public School)",Url:"https://shreejkpublicschool.com/wp-content/uploads/Rules-Regulations_-Inter-School-Solo-Singing-Competition-2.pdf"},{Claim:"Each performance is limited to 5 minutes including set-up time (walking on, adjusting the microphone). Singers may use an instrumental karaoke track or sing a cappella, and must not read lyrics. Songs are chosen from Bollywood hits, Classical, and Western Pop and Rock, in Hindi, English or any recognised Indian regional language.",SourceType:"Primary - the event's own rules document",Source:"Acoustica 2026 - Rules & Regulations: Inter-School Solo Singing Competition (Shree JK Public School)",Url:"https://shreejkpublicschool.com/wp-content/uploads/Rules-Regulations_-Inter-School-Solo-Singing-Competition-2.pdf"},{Claim:"Judging uses five printed criteria with recommended weightage: Vocal Quality and Technique 40, Rhythm and Timing (Laya) 20, Expression and Musicality 20, Stage Presence and Confidence 10, Choice of Song 10 (total 100). A Winner and a Runner-Up are awarded in each category; no points per place are printed.",SourceType:"Primary - the event's own rules document",Source:"Acoustica 2026 - Rules & Regulations: Inter-School Solo Singing Competition (Shree JK Public School)",Url:"https://shreejkpublicschool.com/wp-content/uploads/Rules-Regulations_-Inter-School-Solo-Singing-Competition-2.pdf"},{Claim:"AGE GAP: only classes are printed, not ages. The placeholder age bands are 12-14 (Junior, classes 7-9) and 15-17 (Senior, classes 10-12); the class restriction is kept on each group. The organiser should set the real ages.",SourceType:"Primary - the event's own rules document",Source:"Acoustica 2026 - Rules & Regulations: Inter-School Solo Singing Competition (Shree JK Public School)",Url:"https://shreejkpublicschool.com/wp-content/uploads/Rules-Regulations_-Inter-School-Solo-Singing-Competition-2.pdf"},{Claim:"SCOPE NOTE: the platform has no field for the penalty of 1 mark per 10 seconds over the time limit, the limit of 4 entries per school (maximum 2 per category), the 24-hour karaoke submission deadline, or the song-change approval rule. They are kept as written rules on the registration page and are not enforced by the software.",SourceType:"Primary - the event's own rules document",Source:"Acoustica 2026 - Rules & Regulations: Inter-School Solo Singing Competition (Shree JK Public School)",Url:"https://shreejkpublicschool.com/wp-content/uploads/Rules-Regulations_-Inter-School-Solo-Singing-Competition-2.pdf"}],o="Built from the organiser's 2026 rules and registration forms (one school's inter-school event). Ages are not printed (classes only), so the age bands are placeholders. Left out: the 1-mark-per-10-seconds time penalty, the 4-entries-per-school cap, the karaoke-submission and song-change deadlines, disqualification rules and the registration forms are text only (see the registration page content). No points per place are printed, so the Winner and Runner-Up ranks carry no bonus points. The theme genres are not modelled as items. The event date is printed only as 10/01/2026 in the heading.",t=[{GroupName:"Junior (Classes 7-9)",AgeFrom:12,AgeTo:14,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/upper-primary.webp",RestrictBy:[{ClassName:"7"},{ClassName:"8"},{ClassName:"9"}]},{GroupName:"Senior (Classes 10-12)",AgeFrom:15,AgeTo:17,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/teen.webp",RestrictBy:[{ClassName:"10"},{ClassName:"11"},{ClassName:"12"}]}],i=[{CompetitionItem:0,Title:"Solo Singing",Category:106,CategoryCategoryName:"Music",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/solo-singing.webp",TimeCalculation:"PerHead"}],n=[{CompetitionItem:0,CompetitionItemTitle:"Solo Singing",Group:0,GroupGroupName:"Junior (Classes 7-9)",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:5,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/solo-singing.webp"},{CompetitionItem:0,CompetitionItemTitle:"Solo Singing",Group:0,GroupGroupName:"Senior (Classes 10-12)",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:5,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/solo-singing.webp"}],a=[{Rank:0,RankTitle:"Winner",GradeName:"Winner",ParticipantType:1,ParticipantTypeTitle:"Individual",BonusPoints:0,RoundByPoints:0,MaximumScore:0,Group:0,GroupGroupName:"",CompetitionItem:0,CompetitionItemTitle:""},{Rank:0,RankTitle:"Runner-Up",GradeName:"Runner-Up",ParticipantType:1,ParticipantTypeTitle:"Individual",BonusPoints:0,RoundByPoints:0,MaximumScore:0,Group:0,GroupGroupName:"",CompetitionItem:0,CompetitionItemTitle:""}],r=[{CriteriaName:"Vocal Quality and Technique",SecondValue:"40",Order:1,CompetitionItemTitle:"Solo Singing",GroupGroupName:"",ParticipantTypeTitle:""},{CriteriaName:"Rhythm and Timing (Laya)",SecondValue:"20",Order:2,CompetitionItemTitle:"Solo Singing",GroupGroupName:"",ParticipantTypeTitle:""},{CriteriaName:"Expression and Musicality",SecondValue:"20",Order:3,CompetitionItemTitle:"Solo Singing",GroupGroupName:"",ParticipantTypeTitle:""},{CriteriaName:"Stage Presence and Confidence",SecondValue:"10",Order:4,CompetitionItemTitle:"Solo Singing",GroupGroupName:"",ParticipantTypeTitle:""},{CriteriaName:"Choice of Song",SecondValue:"10",Order:5,CompetitionItemTitle:"Solo Singing",GroupGroupName:"",ParticipantTypeTitle:""}],s={Evidence:e,MaintenanceNote:o,AgeWiseGroups:t,CompetitionItems:i,CompetitionsAssignedToGroup:n,Ranks:a,JudgesCriteria:r};export{t as AgeWiseGroups,i as CompetitionItems,n as CompetitionsAssignedToGroup,e as Evidence,r as JudgesCriteria,o as MaintenanceNote,a as Ranks,s as default};
